-- Criação da Tabela Clientes CREATE TABLE Clientes (     ID INTEGER PRIMARY KEY,     nomeCliente TEXT NOT NULL,     emailCliente TEXT NOT NULL UNIQUE );  -- Criação da Tabela Compras com Chave Estrangeira CREATE TABLE Compras (     CompraID INTEGER PRIMARY KEY,     ClienteID INTEGER,     NomeLivro TEXT NOT NULL,     FOREIGN KEY (ClienteID) REFERENCES Clientes(ID)         ON DELETE CASCADE );  -- Inserção de dados de teste (Opcional) INSERT INTO Clientes (ID, nomeCliente, emailCliente) VALUES  (1, 'Ana Silva', 'ana@email.com'), (2, 'Bruno Costa', 'bruno@email.com');  INSERT INTO Compras (CompraID, ClienteID, NomeLivro) VALUES  (101, 1, 'O Dom Quixote'), (102, 1, '1984'), (103, 2, 'O Pequeno Príncipe');
